class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.13.0/commando_0.13.0_darwin_arm64.tar.gz"
      sha256 "3aa2f9f5fd703b7a06d0e47b6920ca9852264f171daf1a2dd7c7adf26c97e009"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.13.0/commando_0.13.0_darwin_amd64.tar.gz"
      sha256 "be31cb793710755fa998e4571a1161c037b60f40b6be9508c603764423ad064b"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.13.0/commando_0.13.0_linux_arm64.tar.gz"
      sha256 "569416bf8b46f201842c2bb0ba304a1f1f94299e1b7cd3b7c710abe74e13446b"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.13.0/commando_0.13.0_linux_amd64.tar.gz"
      sha256 "17e1dd01b4ad82ceea36f2900834000e18052a4b17dba81ade9436e2f85569cd"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
